package com.tripnest.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;
@Entity @Table(name="accommodations") public class Accommodation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false) String name; @Column(nullable=false) String type; @Column(nullable=false) String city; @Column(nullable=false) String country; @Column(nullable=false) String address; @Column(name="short_description") String shortDescription; @Column(columnDefinition="TEXT") String description; @Column(name="price_per_night",precision=10,scale=2) BigDecimal pricePerNight; @Column(name="max_guests") int maxGuests; BigDecimal rating; boolean active=true; @Column(name="created_at") LocalDateTime createdAt; @Column(name="updated_at") LocalDateTime updatedAt; @OneToMany(fetch=FetchType.EAGER,cascade=CascadeType.ALL,orphanRemoval=true) @JoinColumn(name="accommodation_id") List<AccommodationImage> images=new ArrayList<>(); @ManyToMany(fetch=FetchType.EAGER) @JoinTable(name="accommodation_amenities",joinColumns=@JoinColumn(name="accommodation_id"),inverseJoinColumns=@JoinColumn(name="amenity_id")) Set<Amenity> amenities=new HashSet<>(); @PrePersist void create(){createdAt=updatedAt=LocalDateTime.now();} @PreUpdate void update(){updatedAt=LocalDateTime.now();} public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getType(){return type;} public void setType(String v){type=v;} public String getCity(){return city;} public void setCity(String v){city=v;} public String getCountry(){return country;} public void setCountry(String v){country=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getShortDescription(){return shortDescription;} public void setShortDescription(String v){shortDescription=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public BigDecimal getPricePerNight(){return pricePerNight;} public void setPricePerNight(BigDecimal v){pricePerNight=v;} public int getMaxGuests(){return maxGuests;} public void setMaxGuests(int v){maxGuests=v;} public BigDecimal getRating(){return rating;} public void setRating(BigDecimal v){rating=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} public List<AccommodationImage> getImages(){return images;} public Set<Amenity> getAmenities(){return amenities;} }
